/* covariance.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added to enable optional OpenMP parallelization */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  /* Row-major traversal already matches memory layout (i: rows, j: cols). */
  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving numerical semantics):
   - Compute column means row-by-row for better cache locality.
   - Center the data with a row-major traversal.
   - Reorganize covariance computation to reuse loaded data and
     access both data and covariance in a cache-friendly way:
       * outer loop over features i,
       * middle loop over samples k,
       * inner loop over features j >= i.
     For each cov[i][j], the accumulation order over k is unchanged
     (still k = 0..N-1), so floating-point rounding behavior is
     preserved.
   - Split covariance computation into: zeroing, accumulation, and
     scaling + symmetry, but fused inside a single outer loop on i
     to reduce memory traffic.
   - Add OpenMP pragmas to exploit multi-core parallelism. When
     compiled without OpenMP support, these pragmas are ignored and
     the code runs sequentially with identical results.
*/
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop

  /* 1. Compute column means */

  /* 1a. Initialize means to zero.  Parallelized over columns. */
#pragma omp parallel for schedule(static)
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  /* 1b. Accumulate column sums row-by-row.
     This traverses `data` in row-major order, improving cache use.
     For each column j, the additions are still performed in the
     order i = 0..N-1, matching the original accumulation order. */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_i = data[i]; /* Pointer to row i */
      for (j = 0; j < _PB_M; j++)
        mean[j] += data_i[j];
    }

  /* 1c. Scale to obtain the mean of each column.
     This matches the original single division per column. */
#pragma omp parallel for schedule(static)
  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;


  /* 2. Center the data matrix: data[i][j] -= mean[j].
     Row-major traversal improves locality; each element is updated
     exactly once, as in the original code. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_i = data[i];
      for (j = 0; j < _PB_M; j++)
        data_i[j] -= mean[j];
    }


  /* 3. Compute the covariance matrix of the centered data.

     We compute the upper triangular part (including the diagonal)
     row by row (fixed i), and then mirror it to the lower triangle.

     New loop structure:

       for i in 0..M-1
         zero cov[i][j] for j >= i
         for k in 0..N-1
           x_i = data[k][i]
           for j in i..M-1
             cov[i][j] += x_i * data[k][j]
         scale cov[i][j] by (n-1) and set cov[j][i]

     For a fixed pair (i,j), the sequence of updates to cov[i][j]
     is still exactly:

       cov[i][j] = 0;
       for k = 0..N-1:
         cov[i][j] += data[k][i] * data[k][j];

     i.e., the same order in k as in the original implementation,
     so the floating-point result is bit-identical on a given
     compiler/architecture.
  */

  const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);

#pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE *cov_i;

      /* Pointer to current covariance row i */
      cov_i = cov[i];

      /* 3a. Initialize upper-triangular entries of row i. */
      for (j = i; j < _PB_M; j++)
        cov_i[j] = SCALAR_VAL(0.0);

      /* 3b. Accumulate dot products of centered columns.
         - data[k] is accessed row-wise (contiguous).
         - cov_i[j] is updated along row i (contiguous).
         - x_i (data[k][i]) is loaded once per (i,k) and reused for all j. */
      for (k = 0; k < _PB_N; k++)
        {
          DATA_TYPE *data_k = data[k];
          const DATA_TYPE x_i = data_k[i];

          for (j = i; j < _PB_M; j++)
            cov_i[j] += x_i * data_k[j];
        }

      /* 3c. Scale by (n-1) and enforce symmetry.
         Each pair (i,j) with i <= j is handled exactly once, by the
         iteration owning outer index i, so no data races occur. */
      for (j = i; j < _PB_M; j++)
        {
          DATA_TYPE c = cov_i[j] / denom;
          cov_i[j] = c;
          cov[j][i] = c;
        }
    }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
