#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"

/* ------------------------------------------------------------------------
 * Tunable parameters
 *
 * These constants control when OpenMP parallelization is enabled.
 * They can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DCOVARIANCE_CENTERING_OMP_MIN_N=1 \
 *       -DCOVARIANCE_COV_OMP_MIN_M=1 ...
 *
 * When compiled without OpenMP support, the #pragma omp pragmas are
 * ignored and the code runs sequentially.
 * --------------------------------------------------------------------- */
#ifndef COVARIANCE_CENTERING_OMP_MIN_N
# define COVARIANCE_CENTERING_OMP_MIN_N 32
#endif

#ifndef COVARIANCE_COV_OMP_MIN_M
# define COVARIANCE_COV_OMP_MIN_M 16
#endif


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Local restrict-qualified aliases help the compiler with alias
   * analysis and vectorization.  PolyBench allocates these arrays
   * separately, so this restriction is valid. */
  DATA_TYPE (* restrict data_)[m] = data;
  DATA_TYPE (* restrict cov_)[m]  = cov;
  DATA_TYPE * restrict mean_      = mean;

#pragma scop
  /* 1. Compute column means
   *
   * Original code:
   *   for (j)
   *     mean[j] = 0;
   *     for (i)
   *       mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *
   * This traverses 'data' column-wise (poor locality on row-major).
   *
   * Here, we:
   *   - Initialize all means to 0.
   *   - Traverse 'data' in row-major order and accumulate into mean[j].
   *   - Divide by float_n once per column.
   *
   * For each column j, the additions still occur in increasing i
   * order (i = 0..N-1), so the sequence of floating-point operations
   * for a given mean[j] is unchanged, while cache locality is
   * improved.
   */

  /* Initialize means. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums in row-major order. */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * restrict row = data_[i];

    /* No loop-carried deps on 'mean_' here: each iteration updates a
     * different element, allowing SIMD vectorization. */
    #pragma GCC ivdep
    for (j = 0; j < _PB_M; j++)
      mean_[j] += row[j];
  }

  /* Scale by 1/float_n (hoisted out of inner loops). */
  const DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;
  for (j = 0; j < _PB_M; j++)
    mean_[j] *= inv_float_n;


  /* 2. Center the data: subtract the mean of each column
   *
   * Original code:
   *   for (i)
   *     for (j)
   *       data[i][j] -= mean[j];
   *
   * This is already row-major. We keep that order for locality and
   * additionally parallelize across rows, which are independent.
   *
   * When compiled without OpenMP, the pragma is ignored and the loop
   * executes sequentially.
   */
  #pragma omp parallel for if(_PB_N >= COVARIANCE_CENTERING_OMP_MIN_N) schedule(static) private(j)
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * restrict row = data_[i];

    #pragma GCC ivdep
    for (j = 0; j < _PB_M; j++)
      row[j] -= mean_[j];
  }


  /* 3. Compute covariance matrix
   *
   * Target formula (same as original):
   *   cov[i][j] = sum_{k=0..N-1} data[k][i] * data[k][j]
   *               / (float_n - 1)
   *   cov[j][i] = cov[i][j]
   *
   * We keep the innermost loop over k so that, for each (i, j) pair,
   * the sequence of multiplications and additions over k is identical
   * to the original implementation.
   *
   * Optimizations:
   *   - Keep the running sum in a scalar variable 'sum' (register),
   *     avoiding repeated loads/stores of cov[i][j].
   *   - Hoist division by (float_n - 1) out of k and j loops.
   *   - Parallelize the outer loop over i.  Each (i, j) pair is
   *     computed by exactly one thread, and that thread writes both
   *     cov[i][j] and cov[j][i].  Because the loop only iterates
   *     over j >= i, no other thread touches the same matrix entry,
   *     so there are no data races.
   */

  const DATA_TYPE inv_float_n_minus_one =
      SCALAR_VAL(1.0) / (float_n - SCALAR_VAL(1.0));

  #pragma omp parallel for if(_PB_M >= COVARIANCE_COV_OMP_MIN_M) schedule(static) private(j,k)
  for (i = 0; i < _PB_M; i++)
  {
    for (j = i; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);

      #pragma GCC ivdep
      for (k = 0; k < _PB_N; k++)
        sum += data_[k][i] * data_[k][j];

      const DATA_TYPE val = sum * inv_float_n_minus_one;
      cov_[i][j] = val;
      cov_[j][i] = val; /* enforce symmetry */
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
