  DATA_TYPE (* restrict cov_)[M]  = cov;
  DATA_TYPE * restrict mean_      = mean;

  /* Hoist scalar factors out of loops to avoid repeated divisions. */
  const DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE norm_factor = SCALAR_VAL(1.0) /
                                (float_n - SCALAR_VAL(1.0));

#pragma scop

  /* 1. Compute column means.
   *
   * Original version:
   *   for (j)
   *     mean[j] = 0;
   *     for (i) mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *
   * That accesses 'data' with a large stride in the inner loop.
   * Here we traverse 'data' row-major (i outer, j inner), which is
   * cache-friendly.  We use an OpenMP array reduction so that the
   * parallel implementation remains simple and free of data races.
   */

  /* Initialize means to zero. */
  for (j = 0; j < m_t; ++j)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums: mean[j] = sum_i data[i][j].  The array
   * section reduction mean_[:M] uses the full static extent M; we
   * only touch indices < m_t, so this is safe. */
#pragma omp parallel for if ((long long)n_t * m_t > COV_OMP_MIN_WORK) \
                         schedule(static) reduction(+:mean_[:M])
  for (i = 0; i < n_t; ++i) {
    for (j = 0; j < m_t; ++j) {
      mean_[j] += data_[i][j];
    }
  }

  /* Divide by float_n to obtain the means. */
  for (j = 0; j < m_t; ++j)
    mean_[j] *= inv_float_n;

  /* 2. Center the data matrix: subtract column means.
   *
   *   data[i][j] -= mean[j];
   *
   * The loops are ordered for row-major traversal to maximize cache
   * efficiency.  Each (i,j) element is updated exactly once. */
#pragma omp parallel for if ((long long)n_t * m_t > COV_OMP_MIN_WORK) \
                         schedule(static)
  for (i = 0; i < n_t; ++i) {
    for (j = 0; j < m_t; ++j) {
      data_[i][j] -= mean_[j];
    }
  }

  /* 3. Covariance matrix.
   *
   * We want:
   *   cov[i][j] = (1 / (float_n - 1)) *
   *               sum_k data[k][i] * data[k][j],  for i <= j
   *   cov[j][i] = cov[i][j]
   *
   * Instead of the original i-j-k nest (which repeatedly scans
   * columns of 'data' with a large stride), we reformulate this as a
   * sequence of outer products over the rows:
   *
   *   For each row k, let x = data[k][0..M-1].
   *   Then cov += x^T * x.
   *
   * This accesses 'data' row-wise (contiguous) and reuses each row
   * while it is hot in cache.  We maintain the same mathematical
   * result (up to floating-point round-off).
   */

  /* Initialize the covariance accumulator to zero.  We zero the full
   * matrix; the cost is negligible compared to the O(N*M^2) kernel. */
  for (i = 0; i < m_t; ++i)
    for (j = 0; j < m_t; ++j)
      cov_[i][j] = SCALAR_VAL(0.0);

  /* Accumulate outer products row by row.
   *
   * Parallelization strategy:
   *   - We create a single OpenMP parallel region.
   *   - For each row k, we perform a parallel 'for' over i.
   *   - Each thread owns a disjoint subset of row indices i, and for
   *     a given k updates only cov_[i][j] for its own i.
   *
   * For fixed k:
   *   - Each (i,j) with i <= j is updated exactly once, by the thread
   *     that owns i.
   * Across different k:
   *   - The implicit barrier at the end of each 'omp for' ensures
   *     that updates for row k complete before any thread starts
   *     updating for k+1, so there are no write-write races on
   *     cov_[i][j].
   */
#pragma omp parallel if ((long long)m_t * m_t > COV_OMP_MIN_WORK)
  {
    for (k = 0; k < n_t; ++k) {
      const DATA_TYPE * restrict row_k = data_[k];

#pragma omp for schedule(static)
      for (i = 0; i < m_t; ++i) {
        const DATA_TYPE r_i = row_k[i];
        DATA_TYPE * restrict cov_i = cov_[i];

        /* Only update the upper triangle (j >= i). */
        for (j = i; j < m_t; ++j) {
          cov_i[j] += r_i * row_k[j];
        }
      }
      /* Implicit barrier here (no 'nowait') is essential to avoid
       * concurrent updates to the same cov_[i][j] from different k. */
    }
  }

  /* Normalize and explicitly symmetrize the covariance matrix.
   * The normalization factor is hoisted out of the loops so that each
   * element uses a multiplication instead of a division. */
#pragma omp parallel for if ((long long)m_t * m_t > COV_OMP_MIN_WORK) \
                         schedule(static) private(j)
  for (i = 0; i < m_t; ++i) {
    /* Diagonal element. */
    cov_[i][i] *= norm_factor;

    /* Off-diagonal: compute once and mirror. */
    for (j = i + 1; j < m_t; ++j) {
      DATA_TYPE v = cov_[i][j] * norm_factor;
      cov_[i][j] = v;
      cov_[j][i] = v;
    }
  }

#pragma endscop
}


